// SPDX-License-Identifier: MIT
import assert from 'node:assert/strict';
import test from 'node:test';
import { retry } from '../src/retry.mjs';
import { fetchStatus } from '../src/status-service.mjs';

test('returns the first successful result without another attempt', async () => {
  const seen = [];
  const result = await retry(async (attempt) => {
    seen.push(attempt);
    return 'ready';
  });
  assert.equal(result, 'ready');
  assert.deepEqual(seen, [1]);
});

test('the default permits two failures before a successful third attempt', async () => {
  const seen = [];
  const result = await retry(async (attempt) => {
    seen.push(attempt);
    if (attempt < 3) throw new Error('temporary failure');
    return 'ready';
  });
  assert.equal(result, 'ready');
  assert.deepEqual(seen, [1, 2, 3]);
});

test('fetchStatus retries with no arguments and stops at the first success', async () => {
  const status = { ready: true };
  const calls = [];
  const result = await fetchStatus(function (...args) {
    calls.push(args);
    if (calls.length === 1) throw new Error('temporary failure');
    return status;
  });

  assert.equal(result, status);
  assert.deepEqual(calls, [[], []]);
});

test('fetchStatus throws the last error after three zero-argument calls', async () => {
  const errors = [new Error('first'), new Error('second'), new Error('third')];
  const calls = [];

  await assert.rejects(fetchStatus(function (...args) {
    calls.push(args);
    throw errors[calls.length - 1];
  }), (error) => error === errors[2]);

  assert.deepEqual(calls, [[], [], []]);
});
